package com.primehr.migration;import org.junit.jupiter.api.Test;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Set;import static org.assertj.core.api.Assertions.assertThat;
class SuccessionV50MigrationParityTest{@Test void pairedMigrationsHaveMatchingReadinessStructures()throws Exception{String p=read("db/migration/postgresql/V50__succession_readiness_pool_decision.sql").toLowerCase(),s=read("db/migration/sqlserver/V50__succession_readiness_pool_decision.sql").toLowerCase();Set<String>names=Set.of("succession_readiness_assessment","succession_readiness_gap_item","succession_readiness_panel_assignment","succession_readiness_criterion_finding","succession_pool_decision","ix_succ_ready_cycle_status","ix_succ_ready_gap_assessment","ix_succ_ready_panel_actor","ix_succ_ready_finding_assessment","ix_succ_pool_candidate");for(String m:Set.of(p,s)){assertThat(m).contains(names.toArray(String[]::new));assertThat(m).doesNotContain("rank_score","leaderboard","rsp_referral","appointment_action","salary_action","drop table","delete from");}}private String read(String path)throws IOException{try(var in=getClass().getClassLoader().getResourceAsStream(path)){if(in==null)throw new IOException(path);return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}}
